// Only refresh models that still have no recorded announcement.
// A claim doesn't change after launch, so re-reading every page daily would
// spend tokens to rewrite identical text.
const models = $input.first().json.models ?? [];
return models
  .filter((m) => !m.announcementUrl)
  .slice(0, 10)
  .map((m) => ({ json: m }));

