// Keep only confidently-found claims. Anything the model couldn't source
// is dropped rather than published as an empty or guessed record.
const sources = $('Models missing a claim').all();
const out = [];

const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const src = sources[i]?.json;
  if (!src) continue;

  const block = (items[i].json.content ?? []).find(
    (b) => b.type === 'tool_use' && b.name === 'record_provider_claim',
  );
  const r = block?.input;
  if (!r || r.found !== true) continue;

  const url = String(r.announcementUrl || '').trim();
  const summary = String(r.summary || '').trim();
  if (!/^https?:\/\//.test(url) || summary.length < 20) continue;

  out.push({
    name: src.name,
    slug: src.slug,
    provider: src.provider,
    announcementUrl: url,
    providerBlurb: summary.slice(0, 2000),
    claimedBenchmarks: Array.isArray(r.claimedBenchmarks)
      ? r.claimedBenchmarks
          .filter((b) => b && b.label && b.value)
          .slice(0, 6)
          .map((b) => ({ label: String(b.label).slice(0, 120), value: String(b.value).slice(0, 60) }))
      : [],
    // Flagged so the page can tell readers this text was machine-drafted.
    summaryIsAutoDrafted: true,
  });
}

if (!out.length) return [];
return [{ json: { models: out } }];
